window.kbPageData["views/entry/k-8a560d9db0559d67"] = {"key":"entry/k-8a560d9db0559d67","state":{"route":"entry/k-8a560d9db0559d67"},"node":{"id":"k-8a560d9db0559d67","mode":"k","title":"个人养老金制度","type":"制度与规则","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["社会治理"],"来源主题":["就业、社保与公共服务"],"资料类别":["非时政"]},"directorySummary":"3.个人养老金制度\n个人养老金是指政府政策支持、个人自愿参加、市场化运营、实现养老保险补充功能\n的制度。个人养老金实行个人账户制，缴费完全由参加人个人承担，自主选择购买符合规\n定的储蓄存款、理财产品、商业养老保险、公募基金等金融产品，实行完全积累，按照国家\n有关规定享受税收优惠政策。\n个人养老金的参…","sources":[{"id":"d6c31e0b2d2626ab","label":"个人养老金制度","topic":"就业、社保与公共服务","category":"非时政","text":"3.个人养老金制度\n个人养老金是指政府政策支持、个人自愿参加、市场化运营、实现养老保险补充功能\n的制度。个人养老金实行个人账户制，缴费完全由参加人个人承担，自主选择购买符合规\n定的储蓄存款、理财产品、商业养老保险、公募基金等金融产品，实行完全积累，按照国家\n有关规定享受税收优惠政策。\n个人养老金的参加人应当是在中国境内参加城镇职工基本养老保险或者城乡居民基本\n养老保险的劳动者。\n参加人每年缴纳个人养老金额度上限为 12000 元，参加人每年缴费不得超过该缴费额度\n上限。\n——《个人养老金实施办法》","source":{"doc":"6cbfb01fe723bba64b75","first":11,"last":11,"page":11,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-8a560d9db0559d67":[]}};
